/* ---------- "Learn the trick" lessons, grade 3 English, science and social studies ---------- */
const LESSONS3E=[
 {id:'g3_read_evidence',gen:'reading3',isl:'reading',types:[],title:'Prove it with the text',
  build(){return [
   teachCard('Find the proof',`<p>Good readers don't just guess. They go back to the text and find the <b>sentence that proves</b> the answer.</p><p><i>"Kai's stomach felt full of butterflies as he stood by the pool."</i></p><p>How does Kai feel? <b>Nervous.</b> The proof: <i>"full of butterflies."</i></p>`,'Let\'s try one!'),
   Object.assign(guided(`<i>"Ana yawned and rubbed her eyes."</i> How does Ana feel?`,strChoices('sleepy',['angry','excited']),`What do people do when they are tired?`,`Yawning and rubbing eyes prove she is <b>sleepy</b>.`),{render:c=>esc(c)}),
   Object.assign(guided(`Which words are the proof?`,strChoices('yawned and rubbed her eyes',['Ana','her']),`Which words show the feeling?`,`<b>Yawned and rubbed her eyes</b> show she is sleepy.`),{render:c=>esc(c)})]},
  practice:[0,1,2]},
 {id:'g3_listen_notes',gen:'listen3',isl:'listen',types:[],title:'Listen for the big idea',
  build(){return [
   teachCard('Listen like a detective',`<p>When you listen, think: <b>Who? What? When? Why?</b></p><p>Listen for signal words: <b>first, next, finally, because, if</b>.</p><p>You can press <b>Listen again</b> if you missed something!</p>`,'Let\'s try one!'),
   guided(`A speaker says: <i>"First, wash the apples. Next, cut them. Finally, bake them."</i> What is the second step?`,strChoices('cut the apples',['wash the apples','bake the apples']),`Listen for "Next".`,`"Next" tells the second step: <b>cut the apples</b>.`)]},
  practice:[0,1,2]},
 {id:'g3_words_parts',gen:'words3',isl:'words',types:[],title:'Word parts: prefixes and suffixes',
  build(){return [
   teachCard('Take the word apart',`<p>A <b>prefix</b> goes at the start: <b>un</b>happy (not happy), <b>re</b>do (do again), <b>pre</b>heat (heat before).</p><p>A <b>suffix</b> goes at the end: care<b>ful</b> (full of care), fear<b>less</b> (without fear), teach<b>er</b> (a person who teaches).</p><p>Find the <b>root word</b> in the middle, then add the meanings!</p>`,'Let\'s try one!'),
   guided(`What does <b>unkind</b> mean?`,strChoices('not kind',['very kind','kind again']),`un- means not.`,`Un + kind = <b>not kind</b>.`),
   guided(`What does <b>helpful</b> mean?`,strChoices('full of help',['without help','help again']),`-ful means full of.`,`Help + ful = <b>full of help</b>.`)]},
  practice:[0,8,16]},
 {id:'g3_gram_sentences',gen:'grammar3',isl:'grammar',types:[],title:'Joining sentences',
  build(){return [
   teachCard('And, but, so, because',`<p>Join two sentences with a <b>comma + and / but / so</b>:</p><p><i>"It was cold, <b>so</b> I wore a hat."</i></p><p>Or use <b>because, when, if, after</b> to make a complex sentence:</p><p><i>"I wore a hat <b>because</b> it was cold."</i></p>`,'Let\'s try one!'),
   guided(`Choose the best word: <i>"I was tired, ___ I went to bed early."</i>`,strChoices('so',['but','or']),`The second part is a result.`,`<b>So</b> shows the result.`),
   guided(`Choose the best word: <i>"We stayed inside ___ it was raining."</i>`,strChoices('because',['but','or']),`The second part gives a reason.`,`<b>Because</b> gives the reason.`)]},
  practice:[42,48,30]},
 {id:'g3_write_opinion',gen:'write3',isl:'write',types:[],title:'Opinion, reasons, ending',
  build(){return [
   teachCard('O-R-E',`<p>A strong opinion piece has three parts:</p><p><b>O</b>pinion: <i>"I think dogs are the best pets."</i></p><p><b>R</b>easons with linking words: <i>"<b>because</b> they are loyal. <b>Also</b>, they love to play."</i></p><p><b>E</b>nding: <i>"That is why dogs are the best pets."</i></p>`,'Let\'s try one!'),
   guided(`Which sentence is an <b>opinion</b>?`,strChoices('Pizza is the best lunch.',['Pizza has cheese.','Pizza is round.']),`Could someone disagree?`,`<b>Pizza is the best lunch</b> is what someone thinks.`),
   guided(`Which word introduces a reason?`,strChoices('because',['the','then']),`Which word answers "why"?`,`<b>Because</b> introduces a reason.`)]},
  practice:[0,1,2]},
 {id:'g3_sci_forces',gen:'science3',isl:'science',types:[],title:'Pushes, pulls and magnets',
  build(){return [
   teachCard('Forces make things move',`<p>A <b>force</b> is a push or a pull.</p><p><b>Balanced</b> forces (equal from both sides): nothing moves. <b>Unbalanced</b> forces: the object moves toward the stronger side.</p><p><b>Magnets</b>: opposite poles (N and S) attract; same poles (N and N) repel. Magnets can pull without touching!</p>`,'Let\'s try one!'),
   guided(`Two kids pull a rope equally hard. What happens?`,strChoices('The rope does not move.',['The rope flies away.','The rope breaks in half.']),`Equal pulls are balanced.`,`Balanced forces: <b>the rope does not move</b>.`),
   guided(`What happens when a north pole meets a south pole?`,strChoices('They attract.',['They repel.','Nothing.']),`Opposites attract.`,`N and S <b>attract</b>.`)]},
  practice:[0,1,8]},
 {id:'g3_geo_maps',gen:'geo3',isl:'geo',types:[],title:'Reading a map',
  build(){return [
   teachCard('Map tools',`<p>The <b>compass rose</b> shows directions: north, south, east, west.</p><p>The <b>map key</b> tells what the symbols mean.</p><p>The <b>scale</b> tells real distance: if 1 inch = 10 miles, 3 inches = 30 miles.</p>`,'Let\'s try one!'),
   guided(`Which direction is opposite of east?`,strChoices('west',['north','south']),`Look at a compass rose.`,`East and <b>west</b> are opposites.`),
   guided(`1 inch = 5 miles. How far are towns 2 inches apart?`,strChoices('10 miles',['2 miles','7 miles']),`2 × 5`,`2 × 5 = <b>10 miles</b>.`)]},
  practice:[0,1,2]},
 {id:'g3_hist_govt',gen:'history3',isl:'history',types:[],title:'Three levels of leaders',
  build(){return [
   teachCard('Who leads where?',`<p>A <b>city</b> is led by a <b>mayor</b>.</p><p>A <b>state</b>, like California, is led by a <b>governor</b>.</p><p>The <b>United States</b> is led by the <b>President</b>.</p><p>The national government has three branches: one <b>makes</b> laws (Congress), one <b>carries them out</b> (the President), one <b>decides what they mean</b> (the courts).</p>`,'Let\'s try one!'),
   guided(`Who leads California?`,strChoices('the governor',['the mayor','the President']),`California is a state.`,`A state is led by <b>the governor</b>.`),
   guided(`Which branch makes laws?`,strChoices('the legislative branch (Congress)',['the courts','the President']),`Legislate means to make laws.`,`<b>Congress</b> makes laws.`)]},
  practice:[16,17,18]}
];
